export interface ContentGroup {
  id: string;
  order: number;
  name: string;
  desc: string;
  pages: string;
  icon: string;
}

export interface MotionAsset {
  assetId: string;
  displayId: string;
  pdfPage: number;
  imgUrl: string;
  img2xUrl: string;
  width: number;
  height: number;
}

export interface MotionStep {
  id: string;
  stepNo: string;
  assetId: string;
  displayId: string;
  pdfPage: number;
  imgUrl: string;
  img2xUrl: string;
  width: number;
  height: number;
  desc: string;
  isSymmetricLeft?: boolean;
}

export interface CanonicalLesson {
  id: string;
  title: string;
  groupId: string;
  bookOrder: number;
  contentType: string;
  pdfPages: number[];
  pageRange: string;
  assetCount: number;
  assets: MotionAsset[];
  motions: MotionStep[];
  recommendedPrerequisites: string[];
}

export interface CurriculumStage {
  id: string;
  sequence: number;
  title: string;
  desc: string;
  lessonIds: string[];
}

